.md-render {
  white-space: normal;
  word-break: break-word;
  line-height: 1.6;
  font-size: inherit;
  max-width: 100%;
  min-width: 0;
}
.md-render > :first-child { margin-top: 0; }
.md-render > :last-child { margin-bottom: 0; }
.md-render p { margin: .4em 0; }
.md-render h1, .md-render h2, .md-render h3,
.md-render h4, .md-render h5, .md-render h6 {
  margin: .8em 0 .4em;
  font-weight: 600;
  line-height: 1.35;
}
.md-render h1 { font-size: 1.4em; }
.md-render h2 { font-size: 1.25em; }
.md-render h3 { font-size: 1.1em; }
.md-render h4, .md-render h5, .md-render h6 { font-size: 1em; }
.md-render ul, .md-render ol { margin: .4em 0; padding-left: 1.5em; }
.md-render li { margin: .15em 0; }
.md-render a { color: #0D9488; text-decoration: underline; word-break: break-all; }
.md-render blockquote {
  margin: .5em 0;
  padding: .2em .9em;
  border-left: 3px solid var(--color-neutral-300);
  color: var(--color-neutral-500);
}
.md-render code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: .9em;
  background: var(--color-neutral-100);
  border-radius: 4px;
  padding: .1em .35em;
}
.md-render pre {
  margin: .6em 0;
  padding: .7em 1em;
  border-radius: 8px;
  background: #0F172A;
  color: var(--color-neutral-200);
  overflow-x: auto;
  max-width: 100%;
  min-width: 0;
  white-space: pre;
}
.md-render pre code {
  background: transparent;
  color: inherit;
  padding: 0;
  font-size: .88em;
  white-space: pre;
  word-break: normal;
  overflow-wrap: normal;
}
.md-render table {
  margin: .6em 0;
  border-collapse: collapse;
  max-width: 100%;
  display: block;
  overflow-x: auto;
}
.md-render th, .md-render td {
  border: 1px solid var(--color-neutral-300);
  padding: .3em .6em;
  text-align: left;
}
.md-render th {
  background: var(--color-neutral-50);
  font-weight: 600;
}
.md-render hr { border: none; border-top: 1px solid var(--color-neutral-300); margin: .8em 0; }
.md-render img { max-width: 100%; border-radius: 6px; }
